const NAME='yeobaek-reflection';const KEY='yeobaek-data-v1';let db;let fallback=false;
function readLocal(){const raw=localStorage.getItem(KEY);if(!raw)return {reflections:[],settings:[],dailyQuotes:[]};const data=JSON.parse(raw);for(const k of ['reflections','settings','dailyQuotes'])if(!Array.isArray(data[k]))throw Error('Invalid data');return data}
export async function openStorage(){try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open(NAME,1);req.onupgradeneeded=()=>{const d=req.result;const r=d.createObjectStore('reflections',{keyPath:'id'});r.createIndex('date','date');r.createIndex('quoteId','quoteId');r.createIndex('createdAt','createdAt');d.createObjectStore('settings',{keyPath:'id'});d.createObjectStore('dailyQuotes',{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('blocked'))});db.onversionchange=()=>db.close();return 'indexedDB'}catch{readLocal();localStorage.setItem('yeobaek-storage-check','1');localStorage.removeItem('yeobaek-storage-check');fallback=true;return 'localStorage'}}
export async function all(name){if(fallback)return readLocal()[name];return new Promise((resolve,reject)=>{const tx=db.transaction(name,'readonly');const req=tx.objectStore(name).getAll();tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
export async function put(name,item){if(fallback){const data=readLocal();const i=data[name].findIndex(x=>x.id===item.id);if(i<0)data[name].push(item);else data[name][i]=item;localStorage.setItem(KEY,JSON.stringify(data));return}return new Promise((resolve,reject)=>{const tx=db.transaction(name,'readwrite');tx.objectStore(name).put(item);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
export async function daily(key,quoteId){if(fallback){const data=readLocal();const found=data.dailyQuotes.find(x=>x.id===key);if(found)return found.quoteId;data.dailyQuotes.push({id:key,quoteId});localStorage.setItem(KEY,JSON.stringify(data));return quoteId}return new Promise((resolve,reject)=>{const tx=db.transaction('dailyQuotes','readwrite');const s=tx.objectStore('dailyQuotes');const req=s.get(key);let result;req.onsuccess=()=>{result=req.result?.quoteId||quoteId;if(!req.result)s.put({id:key,quoteId})};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
export async function reset(){if(fallback){localStorage.removeItem(KEY);return}return new Promise((resolve,reject)=>{const tx=db.transaction(['reflections','settings','dailyQuotes'],'readwrite');for(const name of ['reflections','settings','dailyQuotes'])tx.objectStore(name).clear();tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
